/* [LOCK-MODULE: CORE-ASSETS] - CHART ENGINE LOCAL AUTO-CONTENIDO DESKTOP WORKSTATION */

(function (global) {
    class MiniChart {
        constructor(canvas, config) {
            this.canvas = typeof canvas === 'string' ? document.getElementById(canvas) : canvas;
            if (!this.canvas) return;
            this.ctx = this.canvas.getContext('2d');
            this.config = config || {};
            this.type = this.config.type || 'bar';
            this.data = this.config.data || { labels: [], datasets: [] };
            this.options = this.config.options || {};

            // Resize observer para auto-adaptación perfecta al ancho de la tarjeta en escritorio
            this.resizeHandler = () => this.resizeAndRender();
            window.addEventListener('resize', this.resizeHandler);

            this.resizeAndRender();
        }

        resizeAndRender() {
            if (!this.canvas || !this.canvas.parentElement) return;

            const dpr = window.devicePixelRatio || 1;
            const parent = this.canvas.parentElement;
            
            // Medir contenedor padre real en píxeles CSS
            const width = parent.clientWidth || 320;
            const height = parent.clientHeight || 220;

            // Fijar tamaño en el DOM mediante style para evitar expansión accidental
            this.canvas.style.width = width + 'px';
            this.canvas.style.height = height + 'px';
            this.canvas.style.display = 'block';

            // Fijar resolución interna para pantallas Retina
            this.canvas.width = Math.floor(width * dpr);
            this.canvas.height = Math.floor(height * dpr);

            this.ctx.setTransform(1, 0, 0, 1, 0, 0); // reset transform
            this.ctx.scale(dpr, dpr);

            this.width = width;
            this.height = height;

            this.render();
        }

        destroy() {
            window.removeEventListener('resize', this.resizeHandler);
            if (this.ctx && this.width && this.height) {
                this.ctx.clearRect(0, 0, this.width, this.height);
            }
        }

        update() {
            this.resizeAndRender();
        }

        render() {
            if (!this.ctx || this.width <= 0 || this.height <= 0) return;
            this.ctx.clearRect(0, 0, this.width, this.height);

            if (this.type === 'doughnut' || this.type === 'pie') {
                this.renderDoughnut();
            } else if (this.type === 'line') {
                this.renderLine();
            } else {
                this.renderBar();
            }
        }

        renderDoughnut() {
            const dataset = (this.data.datasets && this.data.datasets[0]) || { data: [] };
            const values = dataset.data || [];
            const labels = this.data.labels || [];
            const colors = dataset.backgroundColor || ['#38bdf8', '#f97316', '#34d399', '#a78bfa', '#fb7185'];

            const total = values.reduce((a, b) => a + Number(b), 0) || 1;
            
            // Área de dibujo del anillo
            const legendHeight = 32;
            const availableHeight = this.height - legendHeight;
            const centerX = this.width / 2;
            const centerY = availableHeight / 2 + 5;
            const radius = Math.max(20, Math.min(centerX - 20, centerY - 15));
            const innerRadius = this.type === 'doughnut' ? radius * 0.58 : 0;

            let startAngle = -Math.PI / 2;

            values.forEach((val, idx) => {
                const numericVal = Number(val) || 0;
                if (numericVal <= 0) return;
                const sliceAngle = (numericVal / total) * 2 * Math.PI;
                const endAngle = startAngle + sliceAngle;

                this.ctx.beginPath();
                this.ctx.arc(centerX, centerY, radius, startAngle, endAngle);
                this.ctx.arc(centerX, centerY, innerRadius, endAngle, startAngle, true);
                this.ctx.closePath();
                this.ctx.fillStyle = colors[idx % colors.length];
                this.ctx.fill();
                this.ctx.lineWidth = 2;
                this.ctx.strokeStyle = '#020617';
                this.ctx.stroke();

                startAngle = endAngle;
            });

            // Texto central de total
            if (this.type === 'doughnut') {
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';
                this.ctx.fillStyle = '#ffffff';
                this.ctx.font = 'bold 15px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, monospace';
                this.ctx.fillText(total >= 1000 ? `${(total/1000).toFixed(1)}k` : total.toString(), centerX, centerY - 4);
                this.ctx.fillStyle = '#94a3b8';
                this.ctx.font = '9px monospace';
                this.ctx.fillText('GRAMOS', centerX, centerY + 12);
            }

            // Leyenda compacta inferior
            this.renderLegend(labels, colors, values, this.height - 10);
        }

        renderBar() {
            const dataset = (this.data.datasets && this.data.datasets[0]) || { data: [] };
            const values = (dataset.data || []).map(v => Number(v) || 0);
            const labels = this.data.labels || [];
            const colors = dataset.backgroundColor || ['#10b981', '#0ea5e9', '#ef4444', '#f59e0b'];

            const maxVal = Math.max(...values, 5);
            const padding = { top: 15, right: 15, bottom: 30, left: 35 };
            const chartW = Math.max(10, this.width - padding.left - padding.right);
            const chartH = Math.max(10, this.height - padding.top - padding.bottom);

            // Líneas horizontales de guía (Y)
            this.ctx.strokeStyle = '#1e293b';
            this.ctx.lineWidth = 1;
            this.ctx.fillStyle = '#64748b';
            this.ctx.font = '10px monospace';
            this.ctx.textAlign = 'right';

            for (let i = 0; i <= 3; i++) {
                const y = padding.top + (chartH / 3) * i;
                const val = Math.round(maxVal - (maxVal / 3) * i);
                this.ctx.beginPath();
                this.ctx.moveTo(padding.left, y);
                this.ctx.lineTo(this.width - padding.right, y);
                this.ctx.stroke();
                this.ctx.fillText(val.toString(), padding.left - 6, y + 3);
            }

            // Dibujar Barras
            const n = values.length || 1;
            const slotW = chartW / n;
            const barW = Math.max(8, Math.min(36, slotW * 0.55));

            values.forEach((val, idx) => {
                const barH = (val / maxVal) * chartH;
                const x = padding.left + slotW * idx + (slotW - barW) / 2;
                const y = padding.top + chartH - barH;

                this.ctx.fillStyle = Array.isArray(colors) ? colors[idx % colors.length] : colors;
                
                // Barra redondeada
                this.ctx.beginPath();
                if (this.ctx.roundRect) {
                    this.ctx.roundRect(x, y, barW, barH, [4, 4, 0, 0]);
                } else {
                    this.ctx.rect(x, y, barW, barH);
                }
                this.ctx.fill();

                // Valor sobre la barra si cabe
                if (barH > 15) {
                    this.ctx.fillStyle = '#ffffff';
                    this.ctx.textAlign = 'center';
                    this.ctx.font = 'bold 10px monospace';
                    this.ctx.fillText(val.toString(), x + barW / 2, y + 12);
                }

                // Etiqueta X
                this.ctx.fillStyle = '#94a3b8';
                this.ctx.textAlign = 'center';
                this.ctx.font = '10px sans-serif';
                const lbl = labels[idx] || '';
                this.ctx.fillText(lbl, x + barW / 2, this.height - 10);
            });
        }

        renderLine() {
            const dataset = (this.data.datasets && this.data.datasets[0]) || { data: [] };
            const values = (dataset.data || []).map(v => Number(v) || 0);
            const labels = this.data.labels || [];
            const strokeColor = dataset.borderColor || '#38bdf8';

            const maxVal = Math.max(...values, 100);
            const padding = { top: 20, right: 20, bottom: 30, left: 45 };
            const chartW = Math.max(10, this.width - padding.left - padding.right);
            const chartH = Math.max(10, this.height - padding.top - padding.bottom);

            // Líneas Y
            this.ctx.strokeStyle = '#1e293b';
            this.ctx.lineWidth = 1;
            this.ctx.fillStyle = '#64748b';
            this.ctx.font = '10px monospace';
            this.ctx.textAlign = 'right';

            for (let i = 0; i <= 3; i++) {
                const y = padding.top + (chartH / 3) * i;
                const val = Math.round(maxVal - (maxVal / 3) * i);
                this.ctx.beginPath();
                this.ctx.moveTo(padding.left, y);
                this.ctx.lineTo(this.width - padding.right, y);
                this.ctx.stroke();
                const displayVal = val >= 1000 ? `${Math.round(val/1000)}k` : val.toString();
                this.ctx.fillText(displayVal, padding.left - 6, y + 3);
            }

            // Trazado de Línea de Tendencia
            if (values.length > 0) {
                const step = chartW / Math.max(1, values.length - 1);
                
                // Área sombreada con degradado
                const grad = this.ctx.createLinearGradient(0, padding.top, 0, padding.top + chartH);
                grad.addColorStop(0, 'rgba(56, 189, 248, 0.25)');
                grad.addColorStop(1, 'rgba(56, 189, 248, 0.0)');

                this.ctx.beginPath();
                values.forEach((val, idx) => {
                    const x = padding.left + step * idx;
                    const y = padding.top + chartH - (val / maxVal) * chartH;
                    if (idx === 0) this.ctx.moveTo(x, y);
                    else this.ctx.lineTo(x, y);
                });
                this.ctx.lineTo(padding.left + step * (values.length - 1), padding.top + chartH);
                this.ctx.lineTo(padding.left, padding.top + chartH);
                this.ctx.closePath();
                this.ctx.fillStyle = grad;
                this.ctx.fill();

                // Línea principal
                this.ctx.beginPath();
                values.forEach((val, idx) => {
                    const x = padding.left + step * idx;
                    const y = padding.top + chartH - (val / maxVal) * chartH;
                    if (idx === 0) this.ctx.moveTo(x, y);
                    else this.ctx.lineTo(x, y);
                });
                this.ctx.strokeStyle = strokeColor;
                this.ctx.lineWidth = 2.5;
                this.ctx.stroke();

                // Puntos interactivos
                values.forEach((val, idx) => {
                    const x = padding.left + step * idx;
                    const y = padding.top + chartH - (val / maxVal) * chartH;

                    this.ctx.beginPath();
                    this.ctx.arc(x, y, 4, 0, 2 * Math.PI);
                    this.ctx.fillStyle = strokeColor;
                    this.ctx.fill();
                    this.ctx.lineWidth = 2;
                    this.ctx.strokeStyle = '#0f172a';
                    this.ctx.stroke();

                    // Etiqueta X
                    this.ctx.fillStyle = '#94a3b8';
                    this.ctx.textAlign = 'center';
                    this.ctx.font = '10px sans-serif';
                    this.ctx.fillText(labels[idx] || '', x, this.height - 10);
                });
            }
        }

        renderLegend(labels, colors, values, yPos) {
            const items = labels.slice(0, 4);
            if (items.length === 0) return;

            this.ctx.font = '10px monospace';
            this.ctx.textAlign = 'center';

            const totalWidth = items.reduce((acc, lbl, idx) => {
                const text = `${lbl} (${values[idx] || 0}g)`;
                return acc + this.ctx.measureText(text).width + 24;
            }, 0);

            let currentX = Math.max(10, (this.width - totalWidth) / 2);

            items.forEach((label, idx) => {
                const col = colors[idx % colors.length];
                const text = `${label} (${values[idx] || 0}g)`;
                const textWidth = this.ctx.measureText(text).width;

                this.ctx.fillStyle = col;
                this.ctx.beginPath();
                this.ctx.arc(currentX + 4, yPos - 3, 3.5, 0, 2 * Math.PI);
                this.ctx.fill();

                this.ctx.fillStyle = '#cbd5e1';
                this.ctx.textAlign = 'left';
                this.ctx.fillText(text, currentX + 12, yPos);

                currentX += textWidth + 24;
            });
        }
    }

    global.Chart = MiniChart;
})(window);
